/*
 * prog41_series_sum – reconstructed original program
 *
 * The original binary implements a small state‑machine that parses two
 * command‑line arguments:
 *
 *   argv[1] : mode (integer)
 *   argv[2] : n    (integer, 0 ≤ n ≤ 100000)
 *
 * The program prints one of the following messages and exits:
 *
 *   NO_INPUT      – fewer than two arguments were supplied
 *   BAD_INPUT     – either argument is not a valid integer or n is negative
 *   OUT_OF_RANGE  – n > 100000
 *   BAD_MODE      – mode is not 1, 2 or 3
 *
 * For the three valid modes the program computes a series sum and prints it
 * with six digits after the decimal point:
 *
 *   mode 1 : Σ_{k=1..n} 1/(k*k)          (the Basel series)
 *   mode 2 : Σ_{k=1..n} 1/k               (harmonic series)
 *   mode 3 : Σ_{k=1..n} 1/k               (same as mode 2, different
 *                                         implementation in the original)
 *
 * The constant used in the series is 1.0 (the value stored at address
 * DAT_00102008 in the original binary).
 *
 * The program reproduces exactly the observable behaviour of the original
 * binary (messages on stdout, exit code 0).
 */

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    /* --------------------------------------------------------------------
     * Argument count check
     * -------------------------------------------------------------------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* --------------------------------------------------------------------
     * Parse the two integer arguments, ensuring full conversion.
     * -------------------------------------------------------------------- */
    char *end1, *end2;
    long mode = strtol(argv[1], &end1, 10);
    long n    = strtol(argv[2], &end2, 10);

    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* --------------------------------------------------------------------
     * Range checks for the second argument.
     * -------------------------------------------------------------------- */
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* --------------------------------------------------------------------
     * Compute the requested series.
     * -------------------------------------------------------------------- */
    double sum = 0.0;

    if (mode == 1) {
        /* Σ 1/(k²) */
        for (long k = 1; k <= n; ++k) {
            sum += 1.0 / (k * k);
        }
    } else if (mode == 2 || mode == 3) {
        /* Σ 1/k  (harmonic series) */
        for (long k = 1; k <= n; ++k) {
            sum += 1.0 / k;
        }
    } else {
        puts("BAD_MODE");
        return 0;
    }

    /* --------------------------------------------------------------------
     * Output the result.
     * -------------------------------------------------------------------- */
    printf("%.6f\n", sum);
    return 0;
}
